def replay(events, stock):
    lost=0
    for e in events:
        if e['kind']=='receipt':
            stock += e['quantity']
        else:
            unmet=max(0,e['quantity']-stock)
            if unmet>0:
                lost += unmet
            stock -= min(stock,e['quantity'])
    return stock,lost
